using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation/transient values.
        // Use a fixed seed value instead of DateTime.UtcNow for deterministic migrations.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Document>(b =>
        {
            b.ToContainer("Documents");
            b.HasPartitionKey(d => d.PartitionKey);
            b.HasNoDiscriminator();

            // EF Core 9 breaking change: Cosmos DB discriminator property renamed from
            // "Discriminator" to "$type". For existing documents using "Discriminator",
            // explicitly configure the old property name to avoid data incompatibility.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Document
{
    public string Id { get; set; } = null!;
    public string PartitionKey { get; set; } = null!;
    public string Content { get; set; } = null!;
}

// EF Core 9 breaking change: Synchronous I/O on Cosmos DB now throws by default.
// All Cosmos queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
class CosmosQueryService
{
    // WRONG (throws in EF Core 9):
    // var docs = db.Documents.ToList();

    // CORRECT: use async methods
    public async Task<List<Document>> GetDocumentsAsync(CosmosDbContext db)
    {
        return await db.Documents.ToListAsync();
    }
}

