using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() can no longer be called within a
    // user-started transaction — it now manages its own transaction internally.
    // Removed BeginTransaction()/Commit() wrapping around Migrate().
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

